window.__ASSET_MAP = {"assets/icons/source/edge.png":"data:image/png;base64,","assets/icons/source/elegance.png":"data:image/png;base64,","assets/icons/source/nature.png":"data:image/png;base64,","assets/icons/source/tradition.png":"data:image/png;base64,","assets/icons/source/whimsy.png":"data:image/png;base64,","assets/icons/source/wild.png":"data:image/png;base64,","assets/icons/category/attire-accessories.png":"data:image/png;base64,","assets/icons/category/ceremony.png":"data:image/png;base64,","assets/icons/category/entertainment.png":"data:image/png;base64,","assets/icons/category/favors-gifts.png":"data:image/png;base64,","assets/icons/category/flowers-decorations.png":"data:image/png;base64,","assets/icons/category/food-drink.png":"data:image/png;base64,","assets/icons/category/photography.png":"data:image/png;base64,","assets/icons/category/stationery.png":"data:image/png;base64,","assets/icons/category/transportation.png":"data:image/png;base64,"};

(function(){
  var MAP = window.__ASSET_MAP || {};
  function resolve(p){
    if(!p) return null;
    var i = p.indexOf('assets/');
    if(i>=0) p = p.slice(i);
    return MAP[p] || null;
  }
  function fixImg(img){
    var raw = img.getAttribute('src');
    if(!raw || raw.indexOf('data:')===0) return;
    var d = resolve(raw);
    if(d && img.src !== d) img.src = d;
  }
  function fixBg(el){
    if(!el.style) return;
    var bg = el.style.backgroundImage;
    if(!bg || bg.indexOf('assets/')<0) return;
    var nbg = bg.replace(/assets\/[^"')]+\.(?:png|jpg|jpeg|svg|webp)/g, function(m){
      return resolve(m) || m;
    });
    if(nbg !== bg) el.style.backgroundImage = nbg;
  }
  function sweep(root){
    if(!root || root.nodeType!==1) return;
    if(root.tagName==='IMG') fixImg(root);
    fixBg(root);
    if(root.querySelectorAll){
      root.querySelectorAll('img').forEach(fixImg);
      root.querySelectorAll('*').forEach(fixBg);
    }
  }
  var obs = new MutationObserver(function(muts){
    for(var i=0;i<muts.length;i++){
      var m=muts[i];
      if(m.type==='childList'){ m.addedNodes.forEach(sweep); }
      else if(m.type==='attributes'){
        if(m.target.tagName==='IMG') fixImg(m.target);
        if(m.attributeName==='style') fixBg(m.target);
      }
    }
  });
  function start(){
    sweep(document.body);
    obs.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['src','style']});
  }
  if(document.body) start();
  else document.addEventListener('DOMContentLoaded', start);
})();
